    /// Size in pixels of the view the last acquire returned, or of the next one before any acquire.
    size: ?*const fn (?*ke_gpu_render_target, ?*u32, ?*u32) callconv(.c) void = null,
    /// Texel format of every view acquire returns.
    format: ?*const fn (?*ke_gpu_render_target) callconv(.c) ke_gpu_texture_format = null,
};

